DO $$
DECLARE
  v_version_id TEXT;
BEGIN
  SELECT id INTO v_version_id FROM "BP_PF_v7pp_scoring_versions" 
  WHERE "modelId" = (SELECT id FROM "BP_PF_v7pp_scoring_models" WHERE code = 'PF_V7PP')
    AND status = 'PUBLISHED' ORDER BY "versionNumber" DESC LIMIT 1;


  RAISE NOTICE 'Step 2 done. SSC inserted.';
END $$;
